#include "flat_ws_server_registry.h"
#include "flat_sync.h"
#include "flat_ws_server_frames_internal.h"
#include <stdlib.h>
#include <string.h>
#include <stdio.h>

typedef struct WsListenerRec { uint64_t id; FlatWsServerListener *value; unsigned active; int closing; struct WsListenerRec *next; } WsListenerRec;
typedef struct WsPeerRec { uint64_t id; intptr_t value; unsigned active; int closing; FlatMutex send_mutex; FlatMutex receive_mutex; struct WsPeerRec *next; } WsPeerRec;
struct FlatWsServerRegistry { FlatMutex mutex; FlatCond cond; uint64_t next_id; int closing; WsListenerRec *listeners; WsPeerRec *peers; };
static void regerr(char *e,unsigned long n,const char *s){if(e&&n)snprintf(e,(size_t)n,"%s",s);}
FlatWsServerRegistry *flat_ws_server_registry_create(void){FlatWsServerRegistry*r=(FlatWsServerRegistry*)calloc(1,sizeof *r);if(!r)return NULL;if(flat_mutex_init(&r->mutex)||flat_cond_init(&r->cond)){free(r);return NULL;}r->next_id=1;return r;}
static uint64_t allocid(FlatWsServerRegistry*r){uint64_t id=r->next_id;if(!id||id==UINT64_MAX)return 0;r->next_id++;return id;}
int flat_ws_server_registry_listen(FlatWsServerRegistry*r,const char*h,uint16_t port,int backlog,uint64_t*out,uint16_t*bound,char*e,unsigned long ec){WsListenerRec*x;FlatWsServerListener*l=NULL;uint64_t id;if(out)*out=0;if(!r||!out||!bound)return -1;if(flat_ws_server_listener_open(h,port,backlog,&l,bound,e,ec))return -1;x=(WsListenerRec*)calloc(1,sizeof*x);if(!x){flat_ws_server_listener_close(l);return -1;}flat_mutex_lock(&r->mutex);id=r->closing?0:allocid(r);if(id){x->id=id;x->value=l;x->next=r->listeners;r->listeners=x;*out=id;}flat_mutex_unlock(&r->mutex);if(!id){flat_ws_server_listener_close(l);free(x);regerr(e,ec,"registry is shutting down or ID space exhausted");return -1;}return 0;}
static WsListenerRec *listener_acquire(FlatWsServerRegistry*r,uint64_t id){WsListenerRec*x;for(x=r->listeners;x;x=x->next)if(x->id==id&&!x->closing){x->active++;return x;}return NULL;}
static WsPeerRec *peer_acquire(FlatWsServerRegistry*r,uint64_t id){WsPeerRec*x;for(x=r->peers;x;x=x->next)if(x->id==id&&!x->closing){x->active++;return x;}return NULL;}
static void release_op(FlatWsServerRegistry*r,unsigned *active){flat_mutex_lock(&r->mutex);if(*active)(*active)--;flat_cond_broadcast(&r->cond);flat_mutex_unlock(&r->mutex);}
int flat_ws_server_registry_accept(FlatWsServerRegistry*r,uint64_t lid,long ms,uint64_t*out,char*e,unsigned long ec){WsListenerRec*l;intptr_t fd=-1;WsPeerRec*p;uint64_t id;if(out)*out=0;if(!r||!out)return -1;flat_mutex_lock(&r->mutex);l=listener_acquire(r,lid);flat_mutex_unlock(&r->mutex);if(!l){regerr(e,ec,"unknown or closing listener");return -1;}if(flat_ws_server_listener_accept(l->value,ms,&fd,e,ec)){release_op(r,&l->active);return -1;}p=(WsPeerRec*)calloc(1,sizeof*p);if(!p){flat_ws_server_peer_close(fd);release_op(r,&l->active);return -1;}if(flat_mutex_init(&p->send_mutex)!=0){flat_ws_server_peer_close(fd);free(p);release_op(r,&l->active);return -1;}if(flat_mutex_init(&p->receive_mutex)!=0){flat_mutex_destroy(&p->send_mutex);flat_ws_server_peer_close(fd);free(p);release_op(r,&l->active);return -1;}flat_mutex_lock(&r->mutex);id=(!r->closing&&!l->closing)?allocid(r):0;if(id){p->id=id;p->value=fd;p->next=r->peers;r->peers=p;*out=id;}flat_mutex_unlock(&r->mutex);release_op(r,&l->active);if(!id){flat_ws_server_peer_close(fd);flat_mutex_destroy(&p->receive_mutex);flat_mutex_destroy(&p->send_mutex);free(p);regerr(e,ec,"registry is shutting down");return -1;}return 0;}
int flat_ws_server_registry_upgrade(FlatWsServerRegistry*r,uint64_t id,long ms,char*e,unsigned long ec){WsPeerRec*p;int rc;if(!r)return -1;flat_mutex_lock(&r->mutex);p=peer_acquire(r,id);flat_mutex_unlock(&r->mutex);if(!p){regerr(e,ec,"unknown or closing peer");return -1;}flat_mutex_lock(&p->receive_mutex);flat_mutex_lock(&p->send_mutex);rc=flat_ws_server_peer_accept_upgrade(p->value,ms,e,ec);flat_mutex_unlock(&p->send_mutex);flat_mutex_unlock(&p->receive_mutex);release_op(r,&p->active);return rc;}
int flat_ws_server_registry_send(FlatWsServerRegistry*r,uint64_t id,FlatWsServerOpcode op,const void*d,unsigned long n,char*e,unsigned long ec){WsPeerRec*p;int rc;if(!r)return -1;flat_mutex_lock(&r->mutex);p=peer_acquire(r,id);flat_mutex_unlock(&r->mutex);if(!p){regerr(e,ec,"unknown or closing peer");return -1;}flat_mutex_lock(&p->send_mutex);rc=flat_ws_server_peer_send(p->value,op,d,n,e,ec);flat_mutex_unlock(&p->send_mutex);release_op(r,&p->active);return rc;}
int flat_ws_server_registry_receive(FlatWsServerRegistry*r,uint64_t id,long ms,unsigned long max,FlatWsServerMessage*out,char*e,unsigned long ec){WsPeerRec*p;int rc;if(!r)return -1;flat_mutex_lock(&r->mutex);p=peer_acquire(r,id);flat_mutex_unlock(&r->mutex);if(!p){regerr(e,ec,"unknown or closing peer");return -1;}flat_mutex_lock(&p->receive_mutex);rc=flat_ws_server_peer_receive_internal(p->value,ms,max,out,e,ec,&p->send_mutex);flat_mutex_unlock(&p->receive_mutex);release_op(r,&p->active);return rc;}
int flat_ws_server_registry_close_peer(FlatWsServerRegistry*r,uint64_t id){WsPeerRec*p;if(!r)return -1;flat_mutex_lock(&r->mutex);for(p=r->peers;p&&p->id!=id;p=p->next){}if(!p||p->closing){flat_mutex_unlock(&r->mutex);return -1;}p->closing=1;if(p->value!=(intptr_t)-1)flat_ws_server_peer_shutdown(p->value);while(p->active)flat_cond_wait(&r->cond,&r->mutex);{intptr_t fd=p->value;p->value=(intptr_t)-1;flat_ws_server_peer_close(fd);flat_mutex_destroy(&p->receive_mutex);flat_mutex_destroy(&p->send_mutex);flat_mutex_unlock(&r->mutex);}return 0;}
int flat_ws_server_registry_close_listener(FlatWsServerRegistry*r,uint64_t id){WsListenerRec*p;if(!r)return -1;flat_mutex_lock(&r->mutex);for(p=r->listeners;p&&p->id!=id;p=p->next){}if(!p||p->closing){flat_mutex_unlock(&r->mutex);return -1;}p->closing=1;flat_ws_server_listener_shutdown(p->value);while(p->active)flat_cond_wait(&r->cond,&r->mutex);{FlatWsServerListener*value=p->value;p->value=NULL;flat_ws_server_listener_close(value);flat_mutex_unlock(&r->mutex);}return 0;}
int flat_ws_server_registry_destroy(FlatWsServerRegistry*r){WsListenerRec*l;WsPeerRec*p;if(!r)return -1;flat_mutex_lock(&r->mutex);r->closing=1;for(l=r->listeners;l;l=l->next){l->closing=1;if(l->value)flat_ws_server_listener_shutdown(l->value);}for(p=r->peers;p;p=p->next){p->closing=1;if(p->value!=(intptr_t)-1)flat_ws_server_peer_shutdown(p->value);}for(;;){unsigned busy=0;for(l=r->listeners;l;l=l->next)busy+=l->active;for(p=r->peers;p;p=p->next)busy+=p->active;if(!busy)break;flat_cond_wait(&r->cond,&r->mutex);}flat_mutex_unlock(&r->mutex);while((l=r->listeners)!=NULL){r->listeners=l->next;if(l->value)flat_ws_server_listener_close(l->value);free(l);}while((p=r->peers)!=NULL){r->peers=p->next;if(p->value!=(intptr_t)-1)flat_ws_server_peer_close(p->value);flat_mutex_destroy(&p->receive_mutex);flat_mutex_destroy(&p->send_mutex);free(p);}flat_cond_destroy(&r->cond);flat_mutex_destroy(&r->mutex);free(r);return 0;}
